#!/usr/bin/env python3
"""v0.5.7 GUI patch. Apply after v0.5.6; immutable DSP stays untouched."""
from pathlib import Path
import json,lzma,base64
PAYLOAD=""
patches=json.loads(lzma.decompress(base64.b64decode(PAYLOAD)))
for filename, operations in patches.items():
    p=Path(filename)
    # Some historical Windows source files contain a non-UTF8 bullet;
    # preserve all material except that invalid character.
    raw=p.read_bytes()
    text=raw.decode("utf-8",errors="replace")
    for old,new in operations:
        if text.count(old)!=1:
            raise SystemExit(f"GUI patch anchor mismatch: {filename}: {old[:60]!r}, count={text.count(old)}")
        text=text.replace(old,new,1)
    p.write_text(text,encoding="utf-8")
    print("Applied v0.5.7 changes:",filename,len(operations))
for dsp in ["Source/PluginProcessor.cpp","Source/PluginProcessor.h","Source/CetusLink.h","Source/CetusEQFilters.h"]:
    assert Path(dsp).exists(),dsp
assert "VERSION 0.5.7" in Path("CMakeLists.txt").read_text()
print("GUI v0.5.7 patched successfully; DSP source untouched")
